// JSON修复逻辑：过滤并提取Markdown中的JSON block，或者容错解析
const items = $input.all();
const result = [];
for (const item of items) {
  let text = item.json.output || item.json.text || '';
  if (typeof text === 'object') {
    result.push({ json: text });
    continue;
  }
  let parsed = null;
  try {
    // 尝试直接解析
    parsed = JSON.parse(text);
  } catch (e) {
    // 尝试正则匹配 \`\`\`json ... \`\`\`
    const match = text.match(/\`\`\`json\s*([\s\S]*?)\s*\`\`\`/);
    if (match) {
      try {
        parsed = JSON.parse(match[1]);
      } catch (err) {
        // 尝试清理常见JSON错误
      }
    }
  }
  if (parsed) {
    result.push({ json: parsed });
  } else {
    result.push({ json: item.json });
  }
}
return result;

